#include <stdint.h>
#include "main.h"



int main(void)
{
	RCC_AHB1ENR_t volatile *const pClockContrlReg = ADDR_REG_AHB1ENR;
	GPIOx_MODER_t volatile *const pGPIOAmodeReg = ADDR_REG_GPIO_MODER;
	GPIOx_ODR_t volatile *const pOPdataReg = ADDR_REG_GPIO_ODR;

	//	1. Enable the clock in peripheral A in RCC_AHB1ENR
		pClockContrlReg -> gpio_a_en = CLOCK_ENABLE;

	//	2. Configure the mode as GPIOA pin as OUTPUT
		pGPIOAmodeReg -> moder5 = MODE_CONFG_OUTPUT;


	while(1)
		{
		//	3. SET 5 bit of the output data register to make I/O pin-5 HIGH
				pOPdataReg -> odr5 = PIN_STATE_HIGH;
		//	Introducing the Human Observable Delay
			for(uint32_t volatile i = 0; i <= DELAY_COUNT ; i++);
		//	Turn off the LED
				pOPdataReg -> odr5 = PIN_STATE_LOW;
		//	Again Introducing Delay
			for(uint32_t volatile i=0; i<= DELAY_COUNT ; i++);
		}

}
